-- ============================================================
-- PHASE 1: HELPER FUNCTIONS
-- ============================================================

-- Helper: get current user id from session context safely
CREATE OR REPLACE FUNCTION public.current_user_id()
RETURNS uuid
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
DECLARE
  v_user_id text;
BEGIN
  BEGIN
    v_user_id := current_setting('app.current_user_id', true);
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
  IF v_user_id IS NULL OR v_user_id = '' THEN
    RETURN NULL;
  END IF;
  RETURN v_user_id::uuid;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$$;

-- Helper: check if a user owns a channel
CREATE OR REPLACE FUNCTION public.is_channel_owner(p_channel_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
BEGIN
  IF p_channel_id IS NULL OR p_user_id IS NULL THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1
    FROM public.channels
    WHERE id = p_channel_id
      AND owner_id = p_user_id
  );
END;
$$;

-- Helper: check if a user is a moderator of a channel
CREATE OR REPLACE FUNCTION public.is_channel_moderator(p_channel_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
BEGIN
  IF p_channel_id IS NULL OR p_user_id IS NULL THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1
    FROM public.channel_moderators
    WHERE channel_id = p_channel_id
      AND user_id = p_user_id
  );
END;
$$;

-- Helper: check if user can moderate (is owner OR moderator)
CREATE OR REPLACE FUNCTION public.can_moderate_channel(p_channel_id uuid, p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
AS $$
BEGIN
  IF p_channel_id IS NULL OR p_user_id IS NULL THEN
    RETURN false;
  END IF;
  RETURN (
    public.is_channel_owner(p_channel_id, p_user_id)
    OR
    public.is_channel_moderator(p_channel_id, p_user_id)
  );
END;
$$;

SELECT 'Helper functions created successfully' AS status;
"}

