-- ============================================================
-- PHASE 3: USERS TABLE POLICIES
-- ============================================================

-- Drop existing policies if any (idempotent)
DROP POLICY IF EXISTS "users_select_public_profiles"  ON public.users;
DROP POLICY IF EXISTS "users_update_own_profile"      ON public.users;
DROP POLICY IF EXISTS "users_delete_own_account"      ON public.users;

-- SELECT: Any user can read public profiles (is_public = true)
-- Users can always read their own profile regardless of is_public flag
CREATE POLICY "users_select_public_profiles"
  ON public.users
  FOR SELECT
  USING (
    is_public = true
    OR id = public.current_user_id()
  );

-- UPDATE: Users can only modify their own profile
CREATE POLICY "users_update_own_profile"
  ON public.users
  FOR UPDATE
  USING (
    id = public.current_user_id()
  )
  WITH CHECK (
    id = public.current_user_id()
  );

-- DELETE: Users can only delete their own account
CREATE POLICY "users_delete_own_account"
  ON public.users
  FOR DELETE
  USING (
    id = public.current_user_id()
  );

SELECT 'Users table policies created (SELECT, UPDATE, DELETE)' AS status;
"}

