-- ============================================================
-- PHASE 4: CHANNELS TABLE POLICIES
-- ============================================================

-- Drop existing policies if any
DROP POLICY IF EXISTS "channels_select_public"        ON public.channels;
DROP POLICY IF EXISTS "channels_insert_authenticated" ON public.channels;
DROP POLICY IF EXISTS "channels_update_owner_only"    ON public.channels;
DROP POLICY IF EXISTS "channels_delete_owner_only"    ON public.channels;

-- SELECT: Everyone can read public channels; owners can always see their own channels
CREATE POLICY "channels_select_public"
  ON public.channels
  FOR SELECT
  USING (
    is_public = true
    OR owner_id = public.current_user_id()
  );

-- INSERT: Any authenticated user can create a channel
--         The owner_id must match the current user (prevents creating on behalf of others)
CREATE POLICY "channels_insert_authenticated"
  ON public.channels
  FOR INSERT
  WITH CHECK (
    public.current_user_id() IS NOT NULL
    AND owner_id = public.current_user_id()
  );

-- UPDATE: Only the channel owner can modify channel details
CREATE POLICY "channels_update_owner_only"
  ON public.channels
  FOR UPDATE
  USING (
    owner_id = public.current_user_id()
  )
  WITH CHECK (
    owner_id = public.current_user_id()
  );

-- DELETE: Only the channel owner can delete the channel
CREATE POLICY "channels_delete_owner_only"
  ON public.channels
  FOR DELETE
  USING (
    owner_id = public.current_user_id()
  );

SELECT 'Channels table policies created (SELECT, INSERT, UPDATE, DELETE)' AS status;
"}

