-- ============================================================
-- PHASE 7: CHANNEL_MODERATORS TABLE POLICIES
-- ============================================================

-- Drop existing policies if any
DROP POLICY IF EXISTS "channel_mods_select_all"             ON public.channel_moderators;
DROP POLICY IF EXISTS "channel_mods_insert_owner_only"      ON public.channel_moderators;
DROP POLICY IF EXISTS "channel_mods_delete_owner_or_self"   ON public.channel_moderators;

-- SELECT: Anyone can view moderator lists for channels
CREATE POLICY "channel_mods_select_all"
  ON public.channel_moderators
  FOR SELECT
  USING (
    public.current_user_id() IS NOT NULL
  );

-- INSERT: Only channel owners can add moderators
CREATE POLICY "channel_mods_insert_owner_only"
  ON public.channel_moderators
  FOR INSERT
  WITH CHECK (
    public.is_channel_owner(channel_id, public.current_user_id())
  );

-- DELETE: Channel owners can remove any moderator;
--         Moderators can remove themselves (self-resignation)
CREATE POLICY "channel_mods_delete_owner_or_self"
  ON public.channel_moderators
  FOR DELETE
  USING (
    -- Channel owner can remove any moderator
    public.is_channel_owner(channel_id, public.current_user_id())
    OR
    -- Moderator can remove themselves
    user_id = public.current_user_id()
  );

SELECT 'Channel moderators table policies created (SELECT, INSERT, DELETE)' AS status;
"}

