-- PHASE 8: PERFORMANCE INDEXES FOR RLS POLICIES
-- ============================================================

-- Index: fast lookup of public channels (used in posts/comments SELECT policies)
CREATE INDEX IF NOT EXISTS idx_channels_is_public_owner
  ON public.channels (is_public, owner_id);

-- Index: fast lookup of posts by channel + author (used in comments policies)
CREATE INDEX IF NOT EXISTS idx_posts_channel_author
  ON public.posts (channel_id, author_id);

-- Index: fast lookup of posts by id + author (used in comment UPDATE/DELETE)
CREATE INDEX IF NOT EXISTS idx_posts_id_author
  ON public.posts (id, author_id);

-- Index: fast lookup of comments by post_id + author_id
CREATE INDEX IF NOT EXISTS idx_comments_post_author
  ON public.comments (post_id, author_id);

-- Index: fast lookup of channel_moderators by channel_id (used in can_moderate_channel)
CREATE INDEX IF NOT EXISTS idx_channel_mods_channel_id
  ON public.channel_moderators (channel_id);

-- Index: fast lookup of channels by owner_id (used in is_channel_owner helper)
CREATE INDEX IF NOT EXISTS idx_channels_owner
  ON public.channels (owner_id);

SELECT 'All performance indexes created successfully' AS status;
"}

