-- ============================================================
-- TEST: Helper functions return correct booleans
-- ============================================================

-- Pick a known owner from the live data
WITH owner_row AS (
  SELECT owner_id, id AS channel_id FROM public.channels WHERE owner_id IS NOT NULL LIMIT 1
),
mod_row AS (
  SELECT user_id, channel_id FROM public.channel_moderators LIMIT 1
),
random_user AS (
  SELECT id FROM public.users
  WHERE id NOT IN (SELECT owner_id FROM public.channels WHERE owner_id IS NOT NULL)
    AND id NOT IN (SELECT user_id FROM public.channel_moderators)
  LIMIT 1
)

SELECT
  -- is_channel_owner should be TRUE for an actual owner
  public.is_channel_owner(
    (SELECT channel_id FROM owner_row),
    (SELECT owner_id   FROM owner_row)
  ) AS owner_check_should_be_true,

  -- is_channel_owner should be FALSE for a non-owner
  public.is_channel_owner(
    (SELECT channel_id FROM owner_row),
    (SELECT id FROM random_user)
  ) AS owner_check_should_be_false,

  -- is_channel_moderator should be TRUE for an actual mod
  public.is_channel_moderator(
    (SELECT channel_id FROM mod_row),
    (SELECT user_id    FROM mod_row)
  ) AS mod_check_should_be_true,

  -- can_moderate_channel TRUE for owner
  public.can_moderate_channel(
    (SELECT channel_id FROM owner_row),
    (SELECT owner_id   FROM owner_row)
  ) AS can_moderate_owner_should_be_true,

  -- can_moderate_channel TRUE for moderator
  public.can_moderate_channel(
    (SELECT channel_id FROM mod_row),
    (SELECT user_id    FROM mod_row)
  ) AS can_moderate_mod_should_be_true,

  -- can_moderate_channel FALSE for random user
  public.can_moderate_channel(
    (SELECT channel_id FROM owner_row),
    (SELECT id FROM random_user)
  ) AS can_moderate_random_should_be_false;
"}
